html:
{%- set ctx = dgi_report_context(doc) -%}
{%- set v = ctx.view -%}
{%- set repeat = print_settings and print_settings.repeat_header_footer -%}
<div {% if repeat %}id="header-html" class="hidden-pdf"{% endif %}>
  {% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
<div class="rf">
<style>
  .rf{font-family:Arial,Helvetica,sans-serif;font-size:10px;color:#111;}
  .rf table{border-collapse:collapse;width:100%;}
  .rf h1{font-size:24px;font-weight:normal;text-align:center;margin:4px 0 12px 0;color:#111;}
  .rf h3{font-size:13px;font-weight:normal;margin:16px 0 6px 0;color:#111;}
  .rf .info{width:86%;margin:0 auto;}
  .rf .info td{border-top:1px solid #d9dde3;padding:1px 6px;text-align:right;font-size:9.5px;}
  .rf .info tr:last-child td{border-bottom:1px solid #d9dde3;}
  .rf .info td.k{width:42%;}
  .rf .t{border:1px solid #d9dde3;}
  .rf .t th{font-size:9px;font-weight:bold;color:#111 !important;background:#fff;padding:10px 4px 5px 4px;border-bottom:1px solid #d9dde3;text-align:center;vertical-align:bottom;}
  .rf .t td{font-size:9px;padding:1px 5px;border-bottom:1px solid #eceff3;border-left:1px solid #eceff3;text-align:right;}
  .rf .t td.c{text-align:center;} .rf .t td.l{text-align:left;}
  .rf .t tr.first td{border-top:1px solid #c9ced6;}
  .rf .t tr.tot td{font-weight:bold;border-top:1px solid #c9ced6;}
  .rf .t tr{page-break-inside:avoid;}
  .rf .muted{color:#888;}
  .rf .foot{margin-top:10px;font-size:7.5px;color:#888;text-align:center;}
</style>

<h1>{{ ctx.title }}</h1>
<table class="info">
  <tr><td class="k">Nom</td><td>{{ doc.company_name|e }}</td></tr>
  <tr><td class="k">NIF</td><td>{{ doc.nif|e }}</td></tr>
  <tr><td class="k">ISF</td><td>{{ doc.isf|e }}</td></tr>
  <tr><td class="k">Date du rapport</td><td>{{ ctx.generated_on }}</td></tr>
  <tr><td class="k">Début de période</td><td>{{ ctx["from"] }}</td></tr>
  <tr><td class="k">Fin de période</td><td>{{ ctx.to }}</td></tr>
</table>

{% if ctx.kind != "A" %}
<h3>Section 1: Totaux par type de facture</h3>
<table class="t">
  <thead><tr><th>Type</th><th>Nombre de factures</th><th>Factures incomplètes</th><th>Montant total</th><th>Montant HT</th><th>Montant de la TVA</th><th>Montant de la taxe spécifique</th></tr></thead>
  <tbody>
  {% for t in v.types %}
    <tr><td class="c">{{ t.type }}</td><td class="c">{{ t.count }}</td><td class="c">{{ t.incomplete }}</td><td>{{ t.total }}</td><td>{{ t.ht }}</td><td>{{ t.vat }}</td><td>{{ t.ts }}</td></tr>
  {% endfor %}
  </tbody>
</table>

<h3>Section 2: Totaux par groupe de taxation par type de facture</h3>
<table class="t">
  <thead><tr><th>Type</th><th>Groupe</th><th>Montant total</th><th>Montant HT</th><th>Montant de la TVA</th><th>Montant de la taxe spécifique</th></tr></thead>
  <tbody>
  {% for t in v.types %}{% for g in t.groups %}
    <tr class="{{ 'first' if loop.first else '' }}"><td class="c">{% if loop.first %}{{ t.type }}{% endif %}</td><td class="c">{{ g.group }}</td><td>{{ g.total }}</td><td>{{ g.ht }}</td><td>{{ g.vat }}</td><td>{{ g.ts }}</td></tr>
  {% endfor %}{% endfor %}
  </tbody>
</table>

<h3>Section 3: Totaux par type de paiement</h3>
<table class="t">
  <thead><tr><th style="width:50%;">Type de paiement</th><th>Montant</th></tr></thead>
  <tbody>
  {% for p in v.payments %}<tr><td>{{ p.label }}</td><td>{{ p.amount }}</td></tr>{% endfor %}
  </tbody>
</table>

<h3>Section 4: Réductions</h3>
<table class="t">
  <thead><tr><th>Type de facture</th><th>Montant des réductions</th><th>Montant des réductions d'impôt</th></tr></thead>
  <tbody>
  {% for r in v.reductions %}<tr><td>{{ r.type }}</td><td>{{ r.amount }}</td><td>{{ r.tax }}</td></tr>{% endfor %}
  </tbody>
</table>

<h3>Section 5: Autres enregistrements ayant réduit les ventes (factures d'avoir)</h3>
<table class="t">
  <thead><tr><th>Nature</th><th>Nombre</th><th>Montant total</th></tr></thead>
  <tbody>
  {% for n in v.natures %}<tr><td class="l">{{ n.code }} – {{ n.label }}</td><td class="c">{{ n.count }}</td><td>{{ n.total }}</td></tr>{% endfor %}
  </tbody>
</table>
{% else %}
<h3>Détail par article</h3>
<table class="t">
  <thead><tr><th>#</th><th>Code</th><th>Désignation</th><th>Prix</th><th>Groupe de taxation</th><th>Taux d'impôt</th><th>Quantité vendue</th><th>Quantité retournée</th><th>Quantité en stock</th><th>Montant</th></tr></thead>
  <tbody>
  {% for a in v.articles %}
    <tr><td class="c">{{ loop.index }}</td><td class="l">{{ a.code|e }}</td><td class="l">{{ a.name|e }}</td><td>{{ a.price }}</td><td class="c">{{ a.group }}</td><td class="c">{{ a.rate }}</td><td>{{ a.qty_sold }}</td><td>{{ a.qty_returned }}</td><td>{% if a.stock == "n/a" %}<span class="muted">n/a</span>{% else %}{{ a.stock }}{% endif %}</td><td>{{ a.amount }}</td></tr>
  {% else %}
    <tr><td colspan="10" class="c muted">Aucun article vendu ou retourné sur la période</td></tr>
  {% endfor %}
    <tr class="tot"><td colspan="6" class="l">Total ({{ v.total.count }} articles)</td><td>{{ v.total.qty_sold }}</td><td>{{ v.total.qty_returned }}</td><td></td><td>{{ v.total.amount }}</td></tr>
  </tbody>
</table>
{% endif %}

<div class="foot">{{ doc.company_name|e }} – NIF {{ doc.nif|e }} – ISF {{ doc.isf|e }} – {{ doc.name }} – ERPNext / DGI Compliance v{{ ctx.app_version }}</div>
</div>
<div {% if repeat %}id="footer-html" class="visible-pdf"{% endif %}>
  {% if not no_letterhead and footer %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
  {% if repeat %}<p class="text-center small page-number visible-pdf">{{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}</p>{% endif %}
</div>
